import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 44 · Christmas recipe: snowball cookies / Russian tea cakes (Google Trends 3/11: easy christmas cookie recipes, holiday cookie recipes rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, every Christmas cookie tray in America has a little round white cookie on it, covered in powdered sugar, that melts the second it touches your tongue. Some families call them snowballs. Some call them Russian tea cakes, or Mexican wedding cookies, or butterballs. In our house, my brother Danny called them sneeze cookies, because he always inhaled the sugar.""",
   "snowball cookies powdered sugar plate", "SNEEZE COOKIES")
sc("""But people tell me theirs go flat in the oven, or the sugar melts into a sticky glaze, or the whole cookie crumbles to dust in the tin. So tonight I'm giving you my snowball cookies, every step, and the four mistakes that ruin them. And stay with me, because the last trick is how to keep that snowy coat of sugar, and it's all about timing.""",
   "melted sugar sticky cookies", "THE SUGAR MELTS")

ch("A cookie with many names")
sc("""This little cookie is very old, honey. Nobody knows exactly where it started. Something like it was baked in the Middle East with ground almonds and butter hundreds of years ago, and it traveled to Spain, to Mexico, to Russia and all over Europe. Every country that made it gave it its own name. And every grandmother thinks hers is the original.""",
   "old world bakery cookies", "EVERY COUNTRY NAMED IT")
sc("""Mine came from Mrs. Kowalski, two doors down on Elm Street, who called them kolaczki, though I think she called everything kolaczki. She made them with walnuts. The first time I tried to make them, in nineteen sixty-five, I used margarine to save a nickel. They spread out flat like pancakes, and my husband called them snow puddles.""",
   "1960s kitchen cookies baking", "SNOW PUDDLES")
sc("""That was my first lesson, and I'll tell you about it in a minute. But here's the good news. This is one of the easiest Christmas cookies there is. Only six ingredients, no eggs, no rolling pin, no cookie cutters, and the children can roll the balls. It costs about five dollars for four dozen.""",
   "child rolling cookie dough balls", "ONLY SIX INGREDIENTS")

sc("""In our house, snowball day was the first Saturday of December. My mother made the dough, Danny and I rolled the balls at the kitchen table, and my father was in charge of the sugar bowl, because he said it was the most important job. By the end of the morning, there was powdered sugar on the floor, on the dog, and in my father's eyebrows.""",
   "family kitchen table baking 1950s", "SUGAR ON THE DOG")

ch("What you need")
sc("""Here's what you need, honey, for about four dozen. One cup of butter, two sticks, softened. Half a cup of powdered sugar, plus about a cup and a half more for rolling. One teaspoon of vanilla. Two and a quarter cups of flour. A quarter teaspoon of salt. And three quarters of a cup of pecans or walnuts, chopped very fine.""",
   "butter powdered sugar pecans flour", "THE INGREDIENTS")
sc("""And here's the lesson from my snow puddles. Mistake number one. Margarine, or a spread. Use real butter, every time. Margarine and spreads have water in them, and the cookies melt and spread in the oven. With only six ingredients, butter is the whole flavor of the cookie. Mrs. Kowalski laughed at my snow puddles for a week.""",
   "real butter sticks margarine tub", "REAL BUTTER ONLY")
sc("""And toast the nuts first. Spread them on a baking sheet and bake them at three fifty for six or seven minutes, until they smell warm and buttery. Let them cool all the way, then chop them very fine, almost like coarse sand. Big chunks of nut make the cookies crack and fall apart. Fine nuts hold together and melt in your mouth.""",
   "chopping toasted pecans fine", "LIKE COARSE SAND")

ch("The dough")
sc("""Step one. Beat the soft butter with half a cup of powdered sugar and the vanilla until it's smooth and creamy, about two minutes. Then add the flour, the salt, and the chopped nuts, and mix it on low, or with a wooden spoon, just until it comes together. It'll look crumbly at first. Keep going, and it'll turn into a soft dough.""",
   "mixing butter cookie dough bowl", "IT'LL LOOK CRUMBLY")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now, mistake number two. Skipping the chill. This dough is mostly butter. If it's warm when it goes in the oven, the balls slump into little domes. Cover the bowl and put it in the icebox for at least an hour, until it's firm.""",
   "bowl of dough refrigerator chill", "CHILL ONE HOUR")
sc("""Step two. Heat the oven to three hundred seventy-five. Roll the cold dough into balls about one inch across, about a tablespoon each, between your palms. Roll them quickly, so your warm hands don't melt the butter. Set them on a baking sheet lined with parchment, about an inch apart. They don't spread much if you did the chill right.""",
   "rolling dough balls parchment sheet", "ROLL THEM QUICKLY")
sc("""And make them all the same size, sweetheart. A little cookie scoop helps. If some are big and some are small, the small ones burn and the big ones stay raw in the middle. Mrs. Kowalski weighed hers on her kitchen scale, every single one. She was a very serious woman about cookies.""",
   "cookie scoop dough balls even", "ALL THE SAME SIZE")

sc("""And if your kitchen is warm, sweetheart, put the baking sheet of rolled balls back in the icebox for ten minutes before they go in the oven. Especially if the oven has been on and the room is hot. Cold dough in a hot oven is what keeps them round. Warm dough in a hot oven is how you get snow puddles.""",
   "tray of dough balls refrigerator", "BACK IN THE ICEBOX")

ch("Baking")
sc("""Step three. Bake for ten to twelve minutes. And here's mistake number three. Baking them until they're brown. Snowball cookies should stay pale on top, with just the bottoms a light golden color. Lift one up and peek at the bottom. Light gold underneath means they're done. If the tops brown, they'll be dry and hard.""",
   "pale cookies golden bottoms", "PALE ON TOP")
sc("""So far, real butter, toasted nuts chopped fine, chill the dough, same-size balls, and bake them just until the bottoms are golden. Now the sugar coat, and the trick I promised you. Mistake number four is rolling them in powdered sugar while they're hot. The sugar melts into a sticky, see-through glaze, and they look wet instead of snowy.""",
   "sticky glazed cookies wet", "NOT WHILE HOT")

ch("The snowy coat")
sc("""Here's the timing. Let the cookies cool on the pan for about five minutes, until you can pick one up without it breaking, but it's still warm. Then roll each one gently in a bowl of powdered sugar. This first coat melts just a little and sticks, like a primer on a wall. Set them on a rack and let them cool completely.""",
   "rolling warm cookie powdered sugar", "THE FIRST COAT")
sc("""Then, when they're completely cool, roll them in powdered sugar a second time. This coat stays white and fluffy, like fresh snow on a fence post. Two coats, warm and then cold. That's the whole secret, honey. The first one is the glue, the second one is the snow. Mrs. Kowalski did it this way for sixty years.""",
   "snowball cookies thick white sugar", "THE GLUE AND THE SNOW")
sc("""And for a coat that lasts for days in the tin, mix a tablespoon of cornstarch into every cup of powdered sugar for the second coat. Or use the special non-melting snow sugar that bakers sell. Regular powdered sugar slowly soaks into the butter after a day or two. A light dusting on top right before serving brings back the snow.""",
   "sifting powdered sugar cookies", "SNOW THAT LASTS")

sc("""And sift your powdered sugar first, honey. Powdered sugar sits in the box and gets little hard lumps in it. If you roll your cookies in lumpy sugar, they come out spotty, like a dog with mange, Danny said. Sift it into a wide shallow bowl, and roll three or four cookies at a time, turning them gently with your fingers.""",
   "sifting powdered sugar bowl", "SIFT IT FIRST")

ch("Variations")
sc("""You can change these a hundred ways for Christmas. Use almonds and a little almond extract, the way the Spanish do. Or hazelnuts and a spoon of cocoa in the dough, for chocolate snowballs. Or add the zest of an orange. Or press a chocolate kiss inside each ball before you bake it. My grandson calls those snowballs with a surprise.""",
   "chocolate snowball cookies variety", "A SURPRISE INSIDE")
sc("""And if somebody can't have nuts, honey, leave them out and use a quarter cup more flour, or a cup of finely chopped toasted coconut. And add mini chocolate chips for the children. A friend at church with a nut allergy told me the coconut ones were the first snowball cookie she'd had in thirty years. She took the whole plate home.""",
   "coconut snowball cookies plate", "THIRTY YEARS")

ch("Keeping and giving")
sc("""They keep two weeks in a tin, with wax paper between the layers. And they're perfect for freezing. Freeze the dough balls, unbaked, on a tray, then put them in a bag for three months. Bake them straight from frozen, adding two minutes. Or freeze the baked cookies without the second coat, and roll them in sugar the day you serve them.""",
   "cookie tin wax paper layers", "STRAIGHT FROM FROZEN")
sc("""And put them in little paper candy cups, in a box or a tin, for gifts. They look like a box of snow. I give a tin to the mailman every year, Mr. Hoover's grandson now, who carries our mail just like his grandfather did. He says his wife hides them from the children, and the children hide them from her.""",
   "cookies in paper cups gift tin", "A BOX OF SNOW")

ch("Grandma's kitchen")
sc("""So one more time. Real butter, never margarine. Toasted nuts, chopped fine. Chill the dough an hour. Roll same-size balls. Bake until just the bottoms are golden. Roll them in powdered sugar while they're warm, then again when they're cool. The glue, and then the snow. That's how you get snowball cookies that stay round, snowy, and melt in your mouth.""",
   "snowball cookies Christmas tray", "MELT IN YOUR MOUTH")
sc("""Tell me in the comments, sweetheart. What did your family call these cookies? Snowballs, tea cakes, wedding cookies, or something else? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas cookie plate evening", "WHAT DID YOU CALL THEM?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma44", "Snowball Cookies That NEVER Lose Their Snow (Grandma's 2-Coat Trick)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Snowball cookies, also known as Russian tea cakes, Mexican wedding cookies and butterballs; related to Spanish polvorones and Middle Eastern butter cookies.",
      "Recipe as written by Grandma Ruth: 1 cup butter, 1/2 cup powdered sugar plus about 1 1/2 cups for rolling, 1 tsp vanilla, 2 1/4 cups flour, 1/4 tsp salt, 3/4 cup finely chopped toasted pecans or walnuts; chill 1 hour; 375 F for 10 to 12 minutes; rolled in sugar warm and again cool."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
